const C=flow.get('parking_config');if(!C)return null;
if(msg.config_key&&msg.config_key!==C.config_key)return null;
if(msg._parking?.config_key&&msg._parking.config_key!==C.config_key)return null;
const G=C.group_id,ROLE=C.role,B='parking/'+G,T=C.topics,now=Date.now();
