const labels={ENTERED:'Kendaraan masuk; slot tersimpan',EXITED:'Kendaraan keluar; slot dilepas',FULL:'Parkir penuh',DUPLICATE:'Plat sudah terdaftar',NOT_FOUND:'Plat exit tidak ditemukan',OCR_FAILED:'Plat tidak terbaca stabil',TIMEOUT:'Transaksi kedaluwarsa',ERROR:'Database bermasalah; periksa Debug',OK:'Perubahan tersimpan',CONFLICT:'Data berubah. Perbarui dan ulangi perubahan.',EXPIRED:'Perintah kedaluwarsa; silakan ulangi',INVALID:'Data tidak valid',INVALID_SLOT:'Nomor slot di luar kapasitas',SLOT_OCCUPIED:'Slot tujuan sudah terisi; pilih slot kosong',MISSING:'Data sudah tidak ditemukan',CAPACITY_BLOCKED:'Pindahkan/hapus kendaraan pada slot di atas kapasitas baru terlebih dahulu',ADMIN_ADDED:'Kendaraan ditambahkan admin',ADMIN_UPDATED:'Data/posisi kendaraan diperbarui',ADMIN_DELETED:'Kendaraan dilepas admin',CAPACITY_UPDATED:'Kapasitas diperbarui',HISTORY_UPDATED:'Catatan riwayat diperbarui',HISTORY_DELETED:'Riwayat disembunyikan'};
function send(i,p){const a=[null,null,null,null,null,null];a[i]=p;node.send(a);}
function parse(p){return typeof p==='string'?JSON.parse(p):p;}
// Login dan sesi diperiksa di Node-RED. Kredensial tidak diterbitkan ke MQTT.
const ADMIN_USER=C.admin_username,ADMIN_PASS=C.admin_password;
