 score REAL,
 snapshot_path TEXT,
 message TEXT,
 completed_at TEXT,
 occupancy_after INTEGER,
 PRIMARY KEY(group_id,request_id)
);
CREATE TABLE IF NOT EXISTS parking_v2_active (
 group_id TEXT NOT NULL,
 slot INTEGER NOT NULL CHECK(slot BETWEEN 1 AND 10),
 plate TEXT NOT NULL,
 entered_at TEXT NOT NULL,
 entry_request_id TEXT NOT NULL,
 PRIMARY KEY(group_id,slot),
 UNIQUE(group_id,plate),
 UNIQUE(group_id,entry_request_id)
);
CREATE INDEX IF NOT EXISTS idx_parking_v2_created ON parking_v2_requests(group_id,created_ms);

