CREATE TABLE IF NOT EXISTS parking_v4_numbers(n INTEGER PRIMARY KEY);
WITH RECURSIVE nums(n) AS(SELECT 1 UNION ALL SELECT n+1 FROM nums WHERE n<100) INSERT OR IGNORE INTO parking_v4_numbers SELECT n FROM nums;
CREATE TABLE IF NOT EXISTS parking_v4_active(
 group_id TEXT NOT NULL,slot INTEGER NOT NULL CHECK(slot BETWEEN 1 AND 100),plate TEXT NOT NULL,entered_at TEXT NOT NULL,entry_request_id TEXT NOT NULL,
 PRIMARY KEY(group_id,slot),UNIQUE(group_id,plate),UNIQUE(group_id,entry_request_id));
