CREATE TRIGGER IF NOT EXISTS parking_v4_apply AFTER INSERT ON parking_v4_requests
BEGIN
 UPDATE parking_v4_requests SET status=CASE
  WHEN NEW.status<>'OCR_READY' THEN NEW.status
  WHEN NOT EXISTS(SELECT 1 FROM parking_v4_settings WHERE group_id=NEW.group_id) THEN 'ERROR'
  WHEN NEW.action='entry' AND EXISTS(SELECT 1 FROM parking_v4_active WHERE group_id=NEW.group_id AND plate=NEW.plate) THEN 'DUPLICATE'
  WHEN NEW.action='entry' AND (SELECT COUNT(*) FROM parking_v4_active WHERE group_id=NEW.group_id)>=(SELECT capacity FROM parking_v4_settings WHERE group_id=NEW.group_id) THEN 'FULL'
  WHEN NEW.action='entry' THEN 'ENTERED'
  WHEN EXISTS(SELECT 1 FROM parking_v4_active WHERE group_id=NEW.group_id AND plate=NEW.plate) THEN 'EXITED'
  ELSE 'NOT_FOUND' END,
 assigned_slot=(SELECT slot FROM parking_v4_active WHERE group_id=NEW.group_id AND plate=NEW.plate)
 WHERE group_id=NEW.group_id AND request_id=NEW.request_id;
 INSERT INTO parking_v4_active(group_id,slot,plate,entered_at,entry_request_id)
 SELECT NEW.group_id,n,NEW.plate,strftime('%Y-%m-%dT%H:%M:%fZ','now'),NEW.request_id FROM parking_v4_numbers
 WHERE n<=(SELECT capacity FROM parking_v4_settings WHERE group_id=NEW.group_id)
 AND NOT EXISTS(SELECT 1 FROM parking_v4_active WHERE group_id=NEW.group_id AND slot=n)
 AND (SELECT status FROM parking_v4_requests WHERE group_id=NEW.group_id AND request_id=NEW.request_id)='ENTERED' ORDER BY random() LIMIT 1;
 UPDATE parking_v4_requests SET assigned_slot=(SELECT slot FROM parking_v4_active WHERE group_id=NEW.group_id AND plate=NEW.plate)
 WHERE group_id=NEW.group_id AND request_id=NEW.request_id AND status='ENTERED';
 DELETE FROM parking_v4_active WHERE group_id=NEW.group_id AND plate=NEW.plate
 AND (SELECT status FROM parking_v4_requests WHERE group_id=NEW.group_id AND request_id=NEW.request_id)='EXITED';
 UPDATE parking_v4_requests SET completed_at=strftime('%Y-%m-%dT%H:%M:%fZ','now'),
 occupancy_after=(SELECT COUNT(*) FROM parking_v4_active WHERE group_id=NEW.group_id),
 capacity_after=(SELECT capacity FROM parking_v4_settings WHERE group_id=NEW.group_id)
 WHERE group_id=NEW.group_id AND request_id=NEW.request_id;
 UPDATE parking_meta SET revision=revision+1 WHERE group_id=NEW.group_id;
 INSERT INTO parking_v4_events(group_id,event_key,source,request_id,node_id,action,status,plate,slot,message,occupancy_after,capacity_after,created_ms,completed_at)
 SELECT group_id,'ocr:'||request_id,'ocr',request_id,node_id,action,status,plate,assigned_slot,message,occupancy_after,capacity_after,created_ms,completed_at
 FROM parking_v4_requests WHERE group_id=NEW.group_id AND request_id=NEW.request_id;
END;
CREATE TRIGGER IF NOT EXISTS parking_v4_admin_apply AFTER INSERT ON parking_v4_commands
BEGIN
 UPDATE parking_v4_commands SET status=CASE
  WHEN NEW.expected_revision<>(SELECT revision FROM parking_meta WHERE group_id=NEW.group_id) THEN 'CONFLICT'
  WHEN NEW.expires_ms<CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) THEN 'EXPIRED'
  WHEN NEW.operation='capacity' AND (NEW.capacity IS NULL OR NEW.capacity NOT BETWEEN 1 AND 100) THEN 'INVALID'
  WHEN NEW.operation='capacity' AND EXISTS(SELECT 1 FROM parking_v4_active WHERE group_id=NEW.group_id AND slot>NEW.capacity) THEN 'CAPACITY_BLOCKED'
  WHEN NEW.operation IN('update','delete') AND NOT EXISTS(SELECT 1 FROM parking_v4_active WHERE group_id=NEW.group_id AND plate=NEW.target_plate) THEN 'MISSING'
  WHEN NEW.operation IN('add','update') AND (NEW.new_plate IS NULL OR length(NEW.new_plate)<3) THEN 'INVALID'
  WHEN NEW.operation IN('add','update') AND EXISTS(SELECT 1 FROM parking_v4_active WHERE group_id=NEW.group_id AND plate=NEW.new_plate AND (NEW.operation='add' OR plate<>NEW.target_plate)) THEN 'DUPLICATE'
  WHEN NEW.operation IN('add','update') AND NEW.slot IS NOT NULL AND (NEW.slot<1 OR NEW.slot>(SELECT capacity FROM parking_v4_settings WHERE group_id=NEW.group_id)) THEN 'INVALID_SLOT'
  WHEN NEW.operation IN('add','update') AND NEW.slot IS NOT NULL AND EXISTS(SELECT 1 FROM parking_v4_active WHERE group_id=NEW.group_id AND slot=NEW.slot AND (NEW.operation='add' OR plate<>NEW.target_plate)) THEN 'SLOT_OCCUPIED'
  WHEN NEW.operation='add' AND (SELECT count(*) FROM parking_v4_active WHERE group_id=NEW.group_id)>=(SELECT capacity FROM parking_v4_settings WHERE group_id=NEW.group_id) THEN 'FULL'
  WHEN NEW.operation IN('history_note','history_delete') AND NOT EXISTS(SELECT 1 FROM parking_v4_events WHERE group_id=NEW.group_id AND id=NEW.event_id AND deleted=0) THEN 'MISSING'
  WHEN NEW.operation NOT IN('add','update','delete','capacity','history_note','history_delete') THEN 'INVALID'
  ELSE 'PENDING' END WHERE group_id=NEW.group_id AND command_id=NEW.command_id;
 INSERT INTO parking_v4_active(group_id,slot,plate,entered_at,entry_request_id)
 SELECT NEW.group_id,n,NEW.new_plate,strftime('%Y-%m-%dT%H:%M:%fZ','now'),'admin-'||NEW.command_id FROM parking_v4_numbers
 WHERE (SELECT status FROM parking_v4_commands WHERE group_id=NEW.group_id AND command_id=NEW.command_id)='PENDING'
 AND NEW.operation='add' AND n<=(SELECT capacity FROM parking_v4_settings WHERE group_id=NEW.group_id)
 AND (NEW.slot IS NULL OR n=NEW.slot) AND NOT EXISTS(SELECT 1 FROM parking_v4_active WHERE group_id=NEW.group_id AND slot=n) ORDER BY random() LIMIT 1;
 UPDATE parking_v4_active SET plate=NEW.new_plate,slot=COALESCE(NEW.slot,slot)
 WHERE group_id=NEW.group_id AND plate=NEW.target_plate AND NEW.operation='update'
 AND (SELECT status FROM parking_v4_commands WHERE group_id=NEW.group_id AND command_id=NEW.command_id)='PENDING';
 DELETE FROM parking_v4_active WHERE group_id=NEW.group_id AND plate=NEW.target_plate AND NEW.operation='delete'
 AND (SELECT status FROM parking_v4_commands WHERE group_id=NEW.group_id AND command_id=NEW.command_id)='PENDING';
 UPDATE parking_v4_settings SET capacity=NEW.capacity WHERE group_id=NEW.group_id AND NEW.operation='capacity'
 AND (SELECT status FROM parking_v4_commands WHERE group_id=NEW.group_id AND command_id=NEW.command_id)='PENDING';
 UPDATE parking_v4_events SET note=COALESCE(NEW.note,'') WHERE group_id=NEW.group_id AND id=NEW.event_id AND NEW.operation='history_note'
 AND (SELECT status FROM parking_v4_commands WHERE group_id=NEW.group_id AND command_id=NEW.command_id)='PENDING';
 UPDATE parking_v4_events SET deleted=1 WHERE group_id=NEW.group_id AND id=NEW.event_id AND NEW.operation='history_delete'
 AND (SELECT status FROM parking_v4_commands WHERE group_id=NEW.group_id AND command_id=NEW.command_id)='PENDING';
 UPDATE parking_meta SET revision=revision+1 WHERE group_id=NEW.group_id
 AND (SELECT status FROM parking_v4_commands WHERE group_id=NEW.group_id AND command_id=NEW.command_id)='PENDING';
 UPDATE parking_v4_commands SET status=CASE WHEN status='PENDING' THEN 'OK' ELSE status END,
 completed_at=strftime('%Y-%m-%dT%H:%M:%fZ','now'),occupancy_after=(SELECT count(*) FROM parking_v4_active WHERE group_id=NEW.group_id),
 capacity_after=(SELECT capacity FROM parking_v4_settings WHERE group_id=NEW.group_id)
 WHERE group_id=NEW.group_id AND command_id=NEW.command_id;
 INSERT INTO parking_v4_events(group_id,event_key,source,request_id,node_id,action,status,plate,slot,message,occupancy_after,capacity_after,created_ms,completed_at)
 SELECT group_id,'admin:'||command_id,'admin',command_id,'admin',operation,
 CASE operation WHEN 'add' THEN 'ADMIN_ADDED' WHEN 'update' THEN 'ADMIN_UPDATED' WHEN 'delete' THEN 'ADMIN_DELETED'
 WHEN 'capacity' THEN 'CAPACITY_UPDATED' WHEN 'history_note' THEN 'HISTORY_UPDATED' ELSE 'HISTORY_DELETED' END,
 COALESCE(new_plate,target_plate),(SELECT slot FROM parking_v4_active WHERE group_id=NEW.group_id AND plate=NEW.new_plate),
 'Perubahan dari halaman admin',occupancy_after,capacity_after,created_ms,completed_at
 FROM parking_v4_commands WHERE group_id=NEW.group_id AND command_id=NEW.command_id AND status='OK';
END;
COMMIT;
";msg._parking={stage:"init",config_key:C.config_key};return msg;

// UBAH HANYA BAGIAN INI, lalu Deploy (Full).
const SETTINGS = {
    GROUP_ID: 'kelompok-00',
    NODE_ID: 'node1',          // node1 = entry/master; node2 = exit/monitor
    ADMIN_USERNAME: 'admin',
    ADMIN_PASSWORD: 'admin123'
};
// Semua topik masuk/keluar dibentuk di sini. Tidak memakai wildcard.
const G=SETTINGS.GROUP_ID,L=SETTINGS.NODE_ID;
if(!/^[A-Za-z0-9_-]{1,40}$/.test(G)||!['node1','node2'].includes(L)||!SETTINGS.ADMIN_USERNAME||!SETTINGS.ADMIN_PASSWORD){
    flow.set('parking_config',null);flow.set('ready',false);
    const previous=context.get('subscribed')||[];
    node.send([{action:'unsubscribe',topic:true},null,null]);
    context.set('subscribed',[]);context.set('fingerprint',null);
    node.status({fill:'red',shape:'ring',text:'Konfigurasi tidak valid'});node.error('GROUP_ID harus huruf/angka/_/-, NODE_ID node1 atau node2. Kredensial tidak boleh kosong.');return null;
}
const B='parking/'+G,role=L==='node1'?'master':'monitor';
const topics={state:B+'/state',system:B+'/system',event:B+'/event',nodes:{}};
for(const id of ['node1','node2'])topics.nodes[id]={
    capture:B+'/'+id+'/capture',result:B+'/'+id+'/ocr_result',
    feedback:B+'/'+id+'/feedback',status:B+'/'+id+'/status',python:B+'/'+id+'/python_status',
    adminRequest:B+'/'+id+'/admin/request',adminReply:B+'/'+id+'/admin/reply'
};
const inbound={};
inbound[topics.state]='state';inbound[topics.system]='system';inbound[topics.event]='event';
inbound[topics.nodes[L].adminReply]='admin_reply';
if(role==='master')for(const id of ['node1','node2']){
    const t=topics.nodes[id];inbound[t.result]='result';inbound[t.status]='health';inbound[t.python]='health';inbound[t.adminRequest]='admin_request';
}
const subscriptions=Object.keys(inbound),publishTopics=[topics.state,topics.system,topics.event];
for(const t of Object.values(topics.nodes))publishTopics.push(t.feedback,t.adminRequest,t.adminReply);
const fingerprint=JSON.stringify(SETTINGS),changed=context.get('fingerprint')!==fingerprint||!flow.get('parking_config')||msg.kind==='configure';
let C=flow.get('parking_config');
if(changed){
    const previous=context.get('subscribed')||[];
    node.send([{action:'unsubscribe',topic:true},null,null]);
    C={group_id:G,node_id:L,role,admin_username:SETTINGS.ADMIN_USERNAME,admin_password:SETTINGS.ADMIN_PASSWORD,topics,inbound,publish_topics:publishTopics,config_key:Date.now().toString(36)+'_'+Math.random().toString(36).slice(2)};
    flow.set('parking_config',C);context.set('fingerprint',fingerprint);context.set('subscribed',subscriptions);
    for(const [k,v] of Object.entries({ready:false,db_error:false,health:{},state:null,live_packet:false,state_received:0,master_system:null,system_received:0,system_live:false,published_revision:-1,master_authority:null,events_pending:false,snapshot_pending:false,snapshot_dirty:false,event_seen:{},admin_pending:{},admin_sessions:{},admin_login_attempts:{},last_emitted_event:0}))flow.set(k,v);
}
const text=String(msg.status?.text||'').toLowerCase();
const connected=msg.kind==='broker'&&text.includes('connected')&&!text.includes('disconnected');
const reconnected=connected&&context.get('broker_connected')!==true;
if(msg.kind==='broker')context.set('broker_connected',connected);
if(changed||reconnected){node.send([{action:'unsubscribe',topic:true},null,null]);node.send([{action:'subscribe',topic:subscriptions.map(topic=>({topic,qos:1}))},null,null]);}
if(changed||msg.kind==='configure')node.send([null,{kind:'initialize',config_key:C.config_key},null]);
node.status({fill:'green',shape:'dot',text:G+' / '+L+' / '+role+' / '+subscriptions.length+' topik'});
// Hindari inisialisasi ganda ketika konfigurasi menerima sinyal awal.
return [null,null,['tick','broker'].includes(msg.kind)?msg:{kind:'refresh'}];

const C=flow.get('parking_config');if(!C)return null;
const kind=C.inbound[msg.topic];if(!kind)return null;
let p=msg.payload;
try{if(Buffer.isBuffer(p))p=p.toString('utf8');if(typeof p==='string')p=JSON.parse(p);}catch(_){node.warn('JSON tidak valid pada '+msg.topic);return null;}
if(!p||typeof p!=='object'||Array.isArray(p)||p.group_id!==C.group_id)return null;
if(['result','health'].includes(kind)){
    if(!['node1','node2'].includes(p.node_id))return null;
    const t=C.topics.nodes[p.node_id];
    if(kind==='result'&&msg.topic!==t.result)return null;
    if(kind==='health'&&![t.status,t.python].includes(msg.topic))return null;
}
if(kind==='admin_request'&&(!C.topics.nodes[p.reply_node]||msg.topic!==C.topics.nodes[p.reply_node].adminRequest))return null;
if(kind==='admin_reply'&&(p.reply_node!==C.node_id||msg.topic!==C.topics.nodes[C.node_id].adminReply))return null;
return {kind,topic:msg.topic,payload:p,retain:msg.retain===true,qos:msg.qos,config_key:C.config_key};

const C=flow.get('parking_config');
if(!C||msg.config_key!==C.config_key||!C.publish_topics.includes(msg.topic))return null;
// Node MQTT out tidak memiliki topik tetap; hanya menerima topik persis dari konfigurasi.
return {topic:msg.topic,payload:msg.payload,qos:'1',retain:msg.retain===true};
